#!/bin/sh
# T22-ctx-repo-needle: a 62-file shop backend (src/ledgerly, ~317 KiB), and one
# boundary bug: payments/refunds.py:58, check_refund_window(), rejects day 30
# with `if age_days >= REFUND_WINDOW_DAYS:`; the policy (prompt + docstring)
# allows day 30, so the fix is `>`. setup/ is generated by gen.py next to
# this script (`python3 gen.py --check` proves it is in sync).
#
# Why reading everything cannot fit (context_limit = 16384 in task.toml):
#   mark2 compacts at 0.8 x 16384 = 13107 tokens (compact::DEFAULT_THRESHOLD).
#   The shipped tree is 324482 bytes, of which src/**/*.py is 302812.
#   Even at 6 bytes per token (mark2's own fallback estimate is 4; BPE on
#   code is 3-4) the tree is >= 54080 tokens: 3.3x the whole window and
#   4.1x the compaction threshold, before the system prompt and tool
#   schemas. Measured with the qwen3.5:9b tokenizer (ollama
#   prompt_eval_count, file by file, 2026-11-05): 96478 tokens, i.e. 3.36
#   bytes per token, 5.9x the window and 7.4x the threshold. No single file
#   is over the threshold (largest: docs/errors.md, 6560 tokens), so the
#   smart path fits: grep E-4127 (7 hits, ~0.7 KB) + read refunds.py (5451
#   bytes) + the two twins (3.5 KB) is ~3k tokens at the measured ratio.
#   Dumping the tree through bash is capped at 30000 bytes per call (9 % of
#   it); one read per iteration would need 62 iterations against the
#   default max_turns of 50.
#
# Traps (each has its own FAIL line below):
#   - in-file twin: partial_refund_allowed() in the same file has the very
#     same line and is correct (partial refunds end on day 29): an edit of
#     the bare line is ambiguous, replace_all breaks it;
#   - cross-file twins with the same line, both correct: legacy/refunds_v1.py
#     (dead v1 copy, same E-4127 and message, v1 closed ON day 30) and
#     marketplace/seller_refunds.py (14-day seller window, E-4172, message
#     "seller refund window closed: order is ..."): a sed over the tree or
#     fixing the first grep hit breaks or misses;
#   - shallow-grep decoys: docs/errors.md says E-4127 is raised in
#     ledgerly.legacy.refunds_v1 (stale), api/errors.py and
#     notifications/templates.py carry E-4127 too, shipping/returns.py has
#     "return window closed" with `>` (correct, E-4217).
# Checks: behaviour of the live module (day 30 accepted, day 31 rejected
# with the exact error, partial window unchanged), behaviour of the twins,
# every line of refunds.py except 58 byte-identical, every other shipped
# file byte-identical (cksum manifest). New files are tolerated.
set -eu
# pipefail where the shell has it (bash, dash >= 0.5.12, POSIX.1-2024).
if (set -o pipefail) 2>/dev/null; then set -o pipefail; fi

needle=src/ledgerly/payments/refunds.py
failed=0

if [ ! -f "$needle" ]; then
    echo "FAIL: $needle is missing" >&2
    exit 1
fi

# --- 1. Behaviour ---------------------------------------------------------
# Modules are executed from source with an empty bytecode cache elsewhere:
# a __pycache__ left by the agent's own runs must not shadow an edit.
pycache=$(mktemp -d "${TMPDIR:-/tmp}/t22-pycache.XXXXXX")
trap 'rm -rf "$pycache"' EXIT
trap 'exit 1' HUP INT TERM

if ! PYTHONPYCACHEPREFIX=$pycache PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
import sys
import types
from datetime import date, timedelta

sys.path.insert(0, "src")
failures = []


def load(path, name):
    module = types.ModuleType(name)
    module.__file__ = path
    sys.modules[name] = module
    try:
        with open(path, encoding="utf-8") as source:
            exec(compile(source.read(), path, "exec"), module.__dict__)
    except Exception as error:  # a broken edit is a failure, not a crash
        failures.append("%s does not load: %s: %s" % (path, type(error).__name__, error))
        return None
    return module


D0 = date(2025, 3, 1)


def day(n):
    return D0 + timedelta(days=n)


def outcome(check, n):
    try:
        check(D0, day(n))
    except Exception as error:
        return (getattr(error, "code", type(error).__name__),
                getattr(error, "message", str(error)))
    return None


def closed(code, prefix, n, limit):
    return (code, "%s: order is %d days old (limit %d days)" % (prefix, n, limit))


live = load("src/ledgerly/payments/refunds.py", "t22_live_refunds")
if live is not None:
    window = getattr(live, "check_refund_window", None)
    partial = getattr(live, "partial_refund_allowed", None)
    if window is None or partial is None:
        failures.append("payments/refunds.py lost check_refund_window() or partial_refund_allowed()")
    else:
        expect = [(-1, ("E-4128", "refund requested before delivery: order is -1 days old"))]
        expect += [(n, None) for n in (0, 1, 15, 29, 30)]
        expect += [(n, closed("E-4127", "refund window closed", n, 30)) for n in (31, 45)]
        for n, want in expect:
            got = outcome(window, n)
            if got != want:
                hint = ""
                if n == 30:
                    hint = " (the bug is still there: day 30 is inside the window)"
                failures.append("payments/refunds.py check_refund_window(day %d) -> %r, expected %r%s"
                                % (n, got, want, hint))
        for n, want in [(-1, False), (0, True), (29, True), (30, False), (31, False)]:
            got = partial(D0, day(n))
            if got is not want:
                failures.append(
                    "payments/refunds.py partial_refund_allowed(day %d) = %r, expected %r "
                    "(in-file twin: the same `if age_days >= REFUND_WINDOW_DAYS:` line is correct "
                    "there; replace-all inside refunds.py breaks it)" % (n, got, want))
        evaluate = getattr(live, "evaluate_refund", None)
        request = getattr(live, "RefundRequest", None)
        if evaluate is not None and request is not None:
            cases = [(30, False, 850), (30, True, 850), (29, True, 500)]
            for n, is_partial, want in cases:
                try:
                    got = evaluate(request(order_id="LD-00000001", delivered_on=D0,
                                           requested_on=day(n), amount_cents=1000,
                                           partial=is_partial))
                except Exception as error:
                    got = "%s %s" % (type(error).__name__, error)
                if got != want:
                    failures.append("payments/refunds.py evaluate_refund(day %d, partial=%r) -> %r, expected %r"
                                    % (n, is_partial, got, want))
        else:
            failures.append("payments/refunds.py lost evaluate_refund() or RefundRequest")

twins = [
    ("src/ledgerly/marketplace/seller_refunds.py", "check_seller_refund_window",
     [(0, None), (13, None)] + [(n, closed("E-4172", "seller refund window closed", n, 14)) for n in (14, 15)],
     "cross-file twin with the same line, correct for the 14-day seller window"),
    ("src/ledgerly/legacy/refunds_v1.py", "check_refund_window",
     [(29, None)] + [(n, closed("E-4127", "refund window closed", n, 30)) for n in (30, 31)],
     "dead v1 copy, correct for the v1 rule; docs/errors.md pointing here is stale"),
    ("src/ledgerly/shipping/returns.py", "check_return_window",
     [(30, None), (31, closed("E-4217", "return window closed", 31, 30))],
     "near twin, already inclusive"),
]
for index, (path, name, expect, why) in enumerate(twins):
    module = load(path, "t22_twin_%d" % index)
    check = getattr(module, name, None) if module is not None else None
    if module is not None and check is None:
        failures.append("%s lost %s() (%s)" % (path, name, why))
        continue
    if check is None:
        continue
    for n, want in expect:
        got = outcome(check, n)
        if got != want:
            failures.append("%s %s(day %d) -> %r, expected %r (%s; it must not change)"
                            % (path, name, n, got, want, why))

for line in failures:
    sys.stderr.write("FAIL: " + line + "\n")
sys.exit(1 if failures else 0)
PY
then
    failed=1
fi

# --- 2. The needle file: only line 58 may differ ---------------------------
# awk re-emits each line with "\n", so a lost final newline does not matter.
lines=$(awk 'END { print NR }' "$needle")
if [ "$lines" != "154" ]; then
    echo "FAIL: $needle has $lines lines, expected 154 (the fix is one line; file rewritten?)" >&2
    failed=1
fi
got=$(awk 'NR != 58' "$needle" | cksum)
if [ "$got" != "80310472 5412" ]; then
    echo "FAIL: $needle changed outside line 58 (cksum '$got', expected '80310472 5412')" >&2
    failed=1
fi

# --- 3. Every other shipped file is byte-identical --------------------------
trap_note() {
    case $1 in
        src/ledgerly/legacy/refunds_v1.py)
            echo " [trap: dead v1 copy with the same E-4127 line; the stale docs/errors.md points here]" ;;
        src/ledgerly/marketplace/seller_refunds.py)
            echo " [trap: same line, correct 14-day seller window; replace-all across files]" ;;
        src/ledgerly/shipping/returns.py)
            echo " [trap: near twin \"return window closed\", already inclusive]" ;;
        docs/errors.md|src/ledgerly/api/errors.py|src/ledgerly/notifications/templates.py)
            echo " [trap: E-4127 is mentioned here, but nothing here decides a refund]" ;;
        *) echo "" ;;
    esac
}

manifest=$(mktemp "${TMPDIR:-/tmp}/t22-manifest.XXXXXX")
trap 'rm -rf "$pycache" "$manifest"' EXIT
cat > "$manifest" <<'EOF'
1529202002 992 README.md
1544788818 739 docs/architecture.md
136738466 18294 docs/errors.md
2041324232 123 pyproject.toml
2851438526 19 src/ledgerly/api/__init__.py
4092373008 4800 src/ledgerly/api/errors.py
1937235347 4321 src/ledgerly/api/handlers.py
3596188695 8587 src/ledgerly/api/routes.py
2533937556 8466 src/ledgerly/api/serializers.py
4136723380 23 src/ledgerly/billing/__init__.py
2904641023 8505 src/ledgerly/billing/credit_notes.py
2633143867 8303 src/ledgerly/billing/dunning.py
