4102831810 481 src/ledgerly/util/ids.py
2430144469 876 src/ledgerly/util/money.py
2911653154 746 tests/test_dates.py
2049935930 776 tests/test_money.py
EOF

changed=0
while read -r sum size path; do
    if [ ! -f "$path" ]; then
        echo "FAIL: $path is missing$(trap_note "$path")" >&2
        changed=$((changed + 1))
        continue
    fi
    got=$(cksum < "$path")
    if [ "$got" != "$sum $size" ]; then
        echo "FAIL: $path was modified (cksum '$got', expected '$sum $size')$(trap_note "$path")" >&2
        changed=$((changed + 1))
    fi
done < "$manifest"
if [ "$changed" -gt 0 ]; then
    echo "FAIL: $changed file(s) besides $needle changed; the fix is one line in one file" >&2
    failed=1
fi

exit "$failed"
